import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"]
    events = inputs["cdc_events"]
    watermark = inputs["watermark"]

    # Determine watermark high_ts (events with ts <= high_ts already applied)
    high_ts = watermark["high_ts"].iloc[0] if len(watermark) > 0 else None

    if high_ts is not None:
        new_events = events[events["event_ts"] > high_ts].copy()
    else:
        new_events = events.copy()

    # Deterministic sequential application order: per item, by (event_ts, event_seq)
    new_events = new_events.sort_values(["item_id", "event_ts", "event_seq"], kind="mergesort")

    # Initialize state from the current target snapshot
    state = {}
    for _, row in target.iterrows():
        state[row["item_id"]] = {
            "qty": row["qty_on_hand"],
            "ts": row["last_event_ts"],
            "exists": True,
        }

    for _, row in new_events.iterrows():
        item_id = row["item_id"]
        op = row["op"]
        qty = row["qty"]
        ts = row["event_ts"]

        if item_id not in state:
            state[item_id] = {"qty": 0.0, "ts": pd.NaT, "exists": False}

        s = state[item_id]

        if op == "R":
            if not s["exists"]:
                s["qty"] = 0.0
            s["qty"] = s["qty"] + qty
            s["exists"] = True
        elif op == "A":
            s["qty"] = qty
            s["exists"] = True
        elif op == "D":
            s["exists"] = False
            s["qty"] = 0.0
        # else: unknown op, ignore (defensive, legacy only has R/A/D)

        s["ts"] = ts

    rows = []
    for item_id, s in state.items():
        if s["exists"]:
            rows.append(
                {
                    "item_id": item_id,
                    "qty_on_hand": s["qty"],
                    "last_event_ts": s["ts"],
                }
            )

    result = pd.DataFrame(rows, columns=["item_id", "qty_on_hand", "last_event_ts"])

    if len(result) > 0:
        result["item_id"] = result["item_id"].astype("int64")
        result["qty_on_hand"] = result["qty_on_hand"].astype("float64")
        result["last_event_ts"] = pd.to_datetime(result["last_event_ts"])
        result = result.sort_values("item_id").reset_index(drop=True)
    else:
        result = pd.DataFrame(
            {
                "item_id": pd.Series(dtype="int64"),
                "qty_on_hand": pd.Series(dtype="float64"),
                "last_event_ts": pd.Series(dtype="datetime64[us]"),
            }
        )

    return {"new_snapshot": result}
